/**
 * Walks every organization that has not been deleted, for the fleet-wide sweeps.
 */
import * as orgRepo from "@/server/repositories/organization-repository";
import type { OrgId } from "@/types/common";

/** Organization ids read per page while walking the fleet. */
const ORG_PAGE = 100;

/**
 * Yields every live organization id, one page at a time. A sweep that must
 * reach every tenant iterates this rather than a fixed-size batch, which would
 * silently leave tenants out once the fleet outgrew it. Deleted organizations
 * are never yielded.
 */
export async function* eachLiveOrgId(): AsyncGenerator<OrgId> {
  let afterId: OrgId | null = null;

  for (;;) {
    const page: readonly OrgId[] = await orgRepo.listLiveOrgIds(afterId, ORG_PAGE);
    yield* page;

    const last = page.at(-1);
    if (page.length < ORG_PAGE || last === undefined) return;
    afterId = last;
  }
}

