/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup. A delta is not a
 * recount: `measured_at` is left alone, so the org keeps its place in the
 * rollup queue.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/**
 * The rollup job's work list: live (not deleted) orgs, least recently
 * recounted first. An org that was never recounted — no usage row yet, or only
 * the zeroed placeholder — comes before any that was. Recounting an org moves
 * it to the back; the write-path deltas do not move it at all.
 */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizations.id })
    .from(organizations)
    .leftJoin(organizationUsage, eq(organizationUsage.orgId, organizations.id))
    .where(isNull(organizations.archivedAt))
    .orderBy(
      sql`${organizationUsage.measuredAt} IS NOT NULL`,
      asc(organizationUsage.measuredAt),
      sql`${organizationUsage}.rowid`,
      asc(organizations.id),
    )
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

